def enrich_prompt_with_blackboard_remedies(blackboard, prompt: str, domain: str, bug_sig: str = None) -> str:
    patterns = blackboard.query_patterns(domain, bug_sig)
    if not patterns:
        return prompt
    remedy_lines = []
    for i, pattern in enumerate(patterns[:3]):
        bug_signature = pattern.get("bug_signature", "")
        remedy = pattern.get("remedy", "")
        remedy_lines.append(f"{bug_signature} -> {remedy}")
    remedies_section = "\n# KNOWN DOMAIN REMEDIES:\n" + "\n".join(remedy_lines)
    return prompt + remedies_section


def prioritize_committee_by_competence(blackboard, domain: str, default_portals: typing.List[str], committee_size: int = 5) -> typing.List[str]:
    ranking = blackboard.get_competence_ranking(domain)
    selected = []
    seen = set()
    for entry in ranking:
        if entry.get("reliability", 0) > 0:
            model_id = entry.get("model_id")
            if model_id and model_id not in seen:
                selected.append(model_id)
                seen.add(model_id)
                if len(selected) >= committee_size:
                    return selected
    for portal in default_portals:
        if portal not in seen:
            selected.append(portal)
            seen.add(portal)
            if len(selected) >= committee_size:
                break
    return selected[:committee_size]


