def oracle_collective_fallback(collective_router, Blackboard, system: str, prompt: str, tier: str = 'auto', domain: str = 'oracle_general') -> tuple:
    full_prompt = f'{system}\n\n{prompt}'.strip() if system else prompt
    res = collective_router.route(full_prompt, tier=tier)
    if res.get('ok') and res.get('reply'):
        Blackboard.update_model_competence(
            res.get('portal_id', 'unknown'),
            domain,
            True,
            True,
            float(res.get('latency_ms', 0.0)),
        )
        return (res['reply'], f"collective:{res.get('portal_id')}:{res.get('actual_model', 'unknown')}")
    return (None, 'fallback_none')


