def persist_finding_to_cognitive_blackboard(blackboard, finding: dict) -> str:
    vuln_type = str(finding.get('vuln_type', 'general')).lower()
    url = str(finding.get('url', 'unknown'))
    sev = str(finding.get('severity', 'info')).lower()
    
    hyp_id = f'finding_{vuln_type}_{abs(hash(url)) % 100000}'
    
    conf = 0.95 if sev in ('critical', 'high') else 0.75
    
    blackboard.record_hypothesis(
        hyp_id, 
        vuln_type, 
        str(finding.get('agent', 'swarm')), 
        f'{vuln_type} on {url}', 
        conf, 
        'verified'
    )
    
    blackboard.record_solution_pattern(
        f'pat_{hyp_id}', 
        vuln_type, 
        url, 
        str(finding.get('evidence', finding.get('description', 'verified finding'))), 
        ''
    )
    
    return hyp_id


def get_prior_vuln_patterns(blackboard, vuln_type: str) -> list[dict]:
    return blackboard.query_patterns(str(vuln_type).lower())


