import json
import sqlite3


def check_sqlite_data_version(db_path: str, last_version: int) -> tuple[bool, int]:
    try:
        conn = sqlite3.connect(str(db_path), timeout=5.0)
        try:
            cursor = conn.execute("PRAGMA data_version")
            row = cursor.fetchone()
            current_version = int(row[0])
            return (current_version != last_version, current_version)
        finally:
            conn.close()
    except Exception:
        return (False, last_version)


def resolve_virtual_portal_spec(db_path: str, module_or_portal_id: str) -> dict | None:
    try:
        conn = sqlite3.connect(str(db_path), timeout=5.0)
        try:
            cursor = conn.execute(
                "SELECT portal_id, url, requested_model, actual_model, qualification_state, qualified_roles FROM assistant_external_portals"
            )
            target = module_or_portal_id.strip().lower().replace("-", "_")
            for row in cursor:
                portal_id, url, requested_model, actual_model, qualification_state, qualified_roles = row
                if portal_id.lower().replace("-", "_") == target:
                    roles = json.loads(qualified_roles) if qualified_roles else {}
                    return {
                        "portal_id": portal_id,
                        "url": url,
                        "model_id": actual_model or requested_model or portal_id,
                        "qualification_state": qualification_state,
                        "qualified_roles": roles,
                    }
            return None
        finally:
            conn.close()
    except Exception:
        return None

